"""Separate actual Anny tongue component correspondence; no outer-face proxy."""
from pathlib import Path
import json,numpy as np,trimesh
from scipy.sparse import coo_matrix
from scipy.sparse.csgraph import connected_components
from trimesh.registration import nricp_sumner
R=Path(__file__).resolve().parent.parent;D=R/'research/geometry';F=R/'research/registration'
g=np.fromfile(D/'gnm-vertices.f32','<f4').reshape(-1,3).astype(float)[:,[0,2,1]]*[1,-1,1];gf=np.fromfile(D/'gnm-faces.u32','<u4').reshape(-1,3);gc=np.fromfile(D/'gnm-components.u32','<u4');v=np.fromfile(D/'anny-vertices.f32','<f4').reshape(-1,3).astype(float);f=np.fromfile(D/'anny-faces.u32','<u4').reshape(-1,3);e=np.concatenate([f[:,[0,1]],f[:,[1,2]],f[:,[2,0]]]);_,lab=connected_components(coo_matrix((np.ones(len(e)),(e[:,0],e[:,1])),shape=(len(v),len(v))),directed=False);counts=np.bincount(lab);target_ids=np.flatnonzero(lab==np.flatnonzero(counts==226)[0]);source_ids=np.flatnonzero(gc==5)
def submesh(v,f,ids):
 mask=np.zeros(len(v),bool);mask[ids]=True;faces=f[mask[f].all(1)];lookup=np.full(len(v),-1);lookup[ids]=np.arange(len(ids));return trimesh.Trimesh(v[ids],lookup[faces],process=False)
source=submesh(g,gf,source_ids);target=submesh(v,f,target_ids);reg=np.load(F/'anny-semantic-r3-neutral-registration.npz');M=reg['sourceToTargetMatrix'];source.apply_transform(M);initial=source.vertices.copy();steps=[[1,.001,1,0,0],[10,.001,1,0,0],[30,.001,1,0,0],[100,.001,1,0,0]];record=nricp_sumner(source,target,steps=steps,distance_threshold=.04,return_records=True,use_faces=True,use_vertex_normals=True,face_pairs_type='vertex');fit=np.asarray(record[-1]);q,d,tri=trimesh.proximity.closest_point(target,fit);b=trimesh.triangles.points_to_barycentric(target.triangles[tri],q);np.savez_compressed(F/'anny-tongue-registration.npz',sourceNativeIDs=source_ids,targetNativeTriangleVertices=target_ids[target.faces[tri]],barycentric=b,initial=initial,fitted=fit,sourceFaces=source.faces,sourceToTargetMatrix=M)
report={'source':'Anny226 component confirmed by tongueOut=1 actual27.467mm response and zero outside this component','destination':'GNM original933 tongue vertices','method':'Separate native component neutral NRICP; runtime fixed triangle barycentrics','closestMM':{'median':float(np.median(d)*1000),'p95':float(np.quantile(d,.95)*1000),'max':float(d.max()*1000)},'accepted':False,'remaining':'Native tongueOut+jaw/teeth visual and cross-component intersection review'};(F/'anny-tongue-registration.json').write_text(json.dumps(report,indent=2));print(json.dumps(report,indent=2))
